import { createRequestError } from './errors.js';
export function createHttpClient(input) {
    const baseUrl = new URL(input.baseUrl);
    baseUrl.pathname = baseUrl.pathname.endsWith('/')
        ? baseUrl.pathname
        : `${baseUrl.pathname}/`;
    return {
        getJson(path, options = {}) {
            return sendJson('GET', path, options);
        },
        postJson(path, body, options = {}) {
            return sendJson('POST', path, { ...options, body });
        },
    };
    async function sendJson(method, path, options) {
        const response = await input.fetch(new URL(stripLeadingSlash(path), baseUrl), {
            method,
            headers: createHeaders(options),
            ...(options.body === undefined
                ? {}
                : {
                    body: JSON.stringify(options.body),
                }),
        });
        const payload = await readJson(response);
        if (!response.ok) {
            throw createRequestError(response.status, payload);
        }
        return payload;
    }
    function createHeaders(options) {
        const headers = {
            accept: 'application/json',
        };
        if (options.body !== undefined) {
            headers['content-type'] = 'application/json';
        }
        if (options.accessToken) {
            headers.authorization = `Bearer ${options.accessToken}`;
        }
        return headers;
    }
    function stripLeadingSlash(path) {
        return path.replace(/^\/+/, '');
    }
    async function readJson(response) {
        const text = await response.text();
        if (!text) {
            return null;
        }
        try {
            return JSON.parse(text);
        }
        catch {
            return null;
        }
    }
}
